def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find contiguous row-groups containing non-background cells.
    groups = []
    r = 0
    while r < h:
        if all(v == background for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != background for v in grid[r]):
            r += 1
        groups.append((start, r))

    out = [row[:] for row in grid]

    # Matching groups are repeated patterns; mark missing non-background cells.
    for i in range(len(groups)):
        a0, a1 = groups[i]
        for j in range(i + 1, len(groups)):
            b0, b1 = groups[j]
            if a1 - a0 != b1 - b0:
                continue

            height = a1 - a0
            total = height * w
            matches = sum(
                grid[a0 + dr][c] == grid[b0 + dr][c]
                for dr in range(height)
                for c in range(w)
            )
            if matches / total < 0.5:
                continue

            for dr in range(height):
                for c in range(w):
                    va = grid[a0 + dr][c]
                    vb = grid[b0 + dr][c]
                    if va == background and vb != background:
                        out[a0 + dr][c] = 1
                    elif vb == background and va != background:
                        out[b0 + dr][c] = 1

    return out
